SELECT 'Ivend-Invoice' as "Type",T0."DocEntry" as "DocEntry", T0."DocNum" as "DocNum", T0."DocDate" as "DocDate",  T0."DocTime" as "DocTime", T0."U_CXS_TRID",  T1."ItemCode", T2."ItemName", T3."ItmsGrpCod", T3."ItmsGrpNam",T1."Quantity", T1."UomCode" as "Uom", --T1."NetAmount" as "Price",T1."GrossAmount" as "VATPrice", --((T1."GrossAmount"-T1."NetAmount")*(100-T0."DiscountPercentage")/100) as "VatSum", (T1."NetAmount"*(100-T0."DiscountPercentage")/100) as "LineTotal", T0."DocTotal",T1."VatGroup",((T1."INMPrice"*T1."Quantity")+T1."VatSum") as "LINEGROSS",  T1."PriceAfVAT" as "VATPRICE", T1."LineTotal" as "NetAmount",T1."INMPrice"*T1."Quantity" as "Linetotal", T1."GPTtlBasPr" as "Cost",T1."VatSum",  T4."SlpName" , T1."CodeBars" as "BarCode"  FROM OINV T0 Inner Join INV1 T1 On T0."DocEntry" = T1."DocEntry"  LEFT JOIN OITM T2 ON T1."ItemCode" = T2."ItemCode"  INNER JOIN OITB T3 ON T2."ItmsGrpCod" = T3."ItmsGrpCod" LEFT JOIN OSLP T4 ON T0."SlpCode" = T4."SlpCode"  WHERE  T0."CANCELED"='N' and T2."VatGourpSa"<> T1."VatGroup" and T0."DocDate"  >=[%0] and T0."DocDate" <=[%1] UNION ALL SELECT 'Ivend-Return' as "Type",T0."DocEntry" as "DocEntry", T0."DocNum" as "DocNum", T0."DocDate" as "DocDate",  T0."DocTime" as "DocTime", T0."U_CXS_TRID",  T1."ItemCode", T2."ItemName", T3."ItmsGrpCod", T3."ItmsGrpNam",-T1."Quantity", T1."UomCode" as "Uom", --T1."NetAmount" as "Price",T1."GrossAmount" as "VATPrice", --((T1."GrossAmount"-T1."NetAmount")*(100-T0."DiscountPercentage")/100) as "VatSum", (T1."NetAmount"*(100-T0."DiscountPercentage")/100) as "LineTotal", -T0."DocTotal",T1."VatGroup",-((T1."INMPrice"*T1."Quantity")+T1."VatSum")  as "LINEGROSS",  -T1."PriceAfVAT" as "VATPRICE", -T1."LineTotal" as "NetAmount",-1*T1."INMPrice"*T1."Quantity" as "Linetotal", -T1."GPTtlBasPr" as "Cost",-T1."VatSum",   T4."SlpName" , T1."CodeBars" as "BarCode"  FROM ORIN T0 Inner Join RIN1 T1 On T0."DocEntry" = T1."DocEntry"  LEFT JOIN OITM T2 ON T1."ItemCode" = T2."ItemCode"  INNER JOIN OITB T3 ON T2."ItmsGrpCod" = T3."ItmsGrpCod" LEFT JOIN OSLP T4 ON T0."SlpCode" = T4."SlpCode"  WHERE  T0."CANCELED"='N' and T2."VatGourpSa"<> T1."VatGroup" and T0."DocDate"  >=[%0] and T0."DocDate" <=[%1]
